Definition nbd_bytes (st : nb_state bptr) (b : bits_st bptr) : list Z :=
match search_pure (nb_search_fuel b) (nb_stereo_cb st) b with
| SOnotify tw _ => notify_bytes (if tw then MSG_MORE_THAN_TWO_WB else MSG_INVALID_MODE)
| _ => []
end.
Lemma nbd_prun_inv : forall (st : nb_state bptr) (b : bits_st bptr) q ret d' b' q', nb_encode_submode st = 1 ->
prun (speex_decode (St := pst) p_notify bits_unpack_unsigned_M bits_peek_M bits_advance_M bits_remaining_M (DecNB st) b 0) q = Some ((ret, d', b'), q') ->
p_err q' = p_err q ++ nbd_bytes st b /\
match search_pure (nb_search_fuel b) (nb_stereo_cb st) b with
| SOret r b1 => ret = r /\ d' = DecNB st /\ b' = b1
| SOnotify tw b1 => ret = -2 /\ d' = DecNB st /\ b' = b1
| SOmode mo b1 => exists st', nb_rest_pure st mo b1 = Some (ret, st', b') /\ d' = DecNB st'
| SOunr => False
end.
Proof.
intros st b q ret d' b' q' ES H. rewrite dec_nb_prun, nb_decode_prun in H by exact ES.
unfold nb_decode_res in H. unfold nbd_bytes.
destruct (search_pure (nb_search_fuel b) (nb_stereo_cb st) b) as [r b1 | mo b1 | tw b1 |]; cbn beta iota in H.
- injection H as <- <- <- <-. split; [symmetry; apply app_nil_r| auto].
- destruct (nb_rest_pure st mo b1) as [[[r1 st1] b2]|] eqn:E; [| discriminate].
injection H as <- <- <- <-. split; [symmetry; apply app_nil_r|]. exists st1. split; [reflexivity| reflexivity].
- injection H as <- <- <- <-. split; [reflexivity| auto].
- discriminate.
Qed.

Definition bkeep (b b' : bits_st bptr) : Prop := sb_owner b' = sb_owner b /\ sb_chars b' = sb_chars b /\ sb_buf_size b' = sb_buf_size b.
Lemma bkeep_refl : forall b, bkeep b b.
Proof. intros b. split; [reflexivity| split; reflexivity]. Qed.
Lemma bkeep_trans : forall b1 b2 b3, bkeep b1 b2 -> bkeep b2 b3 -> bkeep b1 b3.
Proof. intros b1 b2 b3 (E1 & E2 & E3) (F1 & F2 & F3). split; [congruence| split; congruence]. Qed.
Lemma bkeep_ub : forall b n, bkeep b (ub b n).
Proof. intros b n. unfold ub, speex_bits_unpack_unsigned, bkeep. destruct (_ || _); (cbn [snd]; unfold set_overflow, set_pos; cbn; split; [reflexivity| split; reflexivity]). Qed.
Lemma bkeep_adv : forall b n, bkeep b (speex_bits_advance b n).
Proof. intros b n. unfold speex_bits_advance, bkeep. destruct (_ || _); (unfold set_overflow, set_pos; cbn; split; [reflexivity| split; reflexivity]). Qed.
Lemma bkeep_ub_r : forall b0 b n, bkeep b0 b -> bkeep b0 (ub b n).
Proof. intros. eapply bkeep_trans; [eassumption| apply bkeep_ub]. Qed.
Lemma bkeep_adv_r : forall b0 b n, bkeep b0 b -> bkeep b0 (speex_bits_advance b n).
Proof. intros. eapply bkeep_trans; [eassumption| apply bkeep_adv]. Qed.
Ltac bkeep_tac := repeat first [ apply bkeep_refl | apply bkeep_ub_r | apply bkeep_adv_r ].
Lemma bkeep_skip : forall b, bkeep b (skip_bits b).
Proof. intros b. unfold skip_bits. bkeep_tac. Qed.
Lemma bkeep_inband : forall sc b, bkeep b (inband_bits sc b).
Proof. intros sc b. unfold inband_bits, stereo_handler_bits. cbv zeta. destruct (_ && _); bkeep_tac. Qed.
Lemma bkeep_user : forall b, bkeep b (user_handler_bits b).
Proof. intros b. unfold user_handler_bits. bkeep_tac. Qed.
Definition sres_keep (b : bits_st bptr) (o : @search_out bptr) : Prop :=
match o with SOret _ b' | SOmode _ b' | SOnotify _ b' => bkeep b b' | SOunr => True end.
Lemma bkeep_search : forall fuel sc (b : bits_st bptr), sres_keep b (search_pure fuel sc b).
Proof.
induction fuel as [|fuel IH]; intros sc b; [exact I|].
rewrite search_pure_S. destruct (speex_bits_remaining b <? 5); [apply bkeep_refl|].
assert (HT : forall bm, bkeep b bm -> sres_keep b (search_tail fuel sc bm)).
{ intros bm K. unfold search_tail. cbv zeta.
destruct (speex_bits_remaining bm <? 4); [exact K|]. destruct (uv bm 4 =? 15); [apply bkeep_ub_r; exact K|].
destruct (uv bm 4 =? 14).
{ pose proof (IH sc (inband_bits sc (ub bm 4))) as H. unfold sres_keep in *. destruct (search_pure fuel sc (inband_bits sc (ub bm 4))); try exact I;
(eapply bkeep_trans; [| exact H]; eapply bkeep_trans; [exact K| eapply bkeep_trans; [apply bkeep_ub| apply bkeep_inband]]). }
destruct (uv bm 4 =? 13).
{ pose proof (IH sc (user_handler_bits (ub bm 4))) as H. unfold sres_keep in *. destruct (search_pure fuel sc (user_handler_bits (ub bm 4))); try exact I;
(eapply bkeep_trans; [| exact H]; eapply bkeep_trans; [exact K| eapply bkeep_trans; [apply bkeep_ub| apply bkeep_user]]). }
destruct (8 <? uv bm 4); apply bkeep_ub_r; exact K. }
unfold search_head. cbv zeta. destruct (negb (uv b 1 =? 0)); [| apply HT, bkeep_ub].
destruct (speex_bits_remaining (skip_bits (ub b 1)) <? 5); [eapply bkeep_trans; [apply bkeep_ub| apply bkeep_skip]|].
destruct (negb (uv (skip_bits (ub b 1)) 1 =? 0)).
- destruct (negb (uv (skip_bits (ub (skip_bits (ub b 1)) 1)) 1 =? 0)).
+ apply bkeep_ub_r. eapply bkeep_trans; [| apply bkeep_skip]. apply bkeep_ub_r. eapply bkeep_trans; [apply bkeep_ub| apply bkeep_skip].
+ apply HT. apply bkeep_ub_r. eapply bkeep_trans; [| apply bkeep_skip]. apply bkeep_ub_r. eapply bkeep_trans; [apply bkeep_ub| apply bkeep_skip].
- apply HT. apply bkeep_ub_r. eapply bkeep_trans; [apply bkeep_ub| apply bkeep_skip].
Qed.
Definition sres_ret (o : @search_out bptr) : Prop := match o with SOret r _ => r = -1 | _ => True end.
Lemma search_ret_m1 : forall fuel sc (b : bits_st bptr), sres_ret (search_pure fuel sc b).
Proof.
induction fuel as [|fuel IH]; intros sc b; [exact I|].
rewrite search_pure_S. destruct (speex_bits_remaining b <? 5); [reflexivity|].
assert (HT : forall bm, sres_ret (search_tail fuel sc bm)).
{ intros bm. unfold search_tail. cbv zeta.
destruct (speex_bits_remaining bm <? 4); [reflexivity|]. destruct (uv bm 4 =? 15); [reflexivity|].
destruct (uv bm 4 =? 14); [apply IH|]. destruct (uv bm 4 =? 13); [apply IH|]. destruct (8 <? uv bm 4); exact I. }
unfold search_head. cbv zeta. destruct (negb (uv b 1 =? 0)); [| apply HT].
destruct (speex_bits_remaining (skip_bits (ub b 1)) <? 5); [reflexivity|].
destruct (negb (uv (skip_bits (ub b 1)) 1 =? 0)); [| apply HT].
destruct (negb (uv (skip_bits (ub (skip_bits (ub b 1)) 1)) 1 =? 0)); [exact I| apply HT].
Qed.

Lemma bkeep_lsp : forall k b, bkeep b (lsp_bits k b).
Proof. intros k b. destruct k; unfold lsp_bits; bkeep_tac. Qed.
Lemma bkeep_segD : forall st sm b, bkeep b (segD_bits st sm b).
Proof.
intros st sm b. unfold segD_bits, segD_b3, segD_b2, segD_b1.
destruct (nb_submodeID st =? 1); destruct (negb (sm_forced_pitch_gain sm =? 0)); destruct (negb (sm_lbr_pitch sm =? -1)); bkeep_tac.
Qed.
Lemma bkeep_scb : forall n hs sb b, bkeep b (scb_bits n hs sb b).
Proof.
induction n as [|n IH]; intros hs sb b; cbn [scb_bits]; [apply bkeep_refl|].
eapply bkeep_trans; [| apply IH]. destruct (negb (hs =? 0)); bkeep_tac.
Qed.
Lemma bkeep_subframe : forall sm olp sub st b st' b', subframe_pure sm olp sub st b = Some (st', b') -> bkeep b b'.
Proof.
intros sm olp sub st b st' b' E. unfold subframe_pure in E.
destruct (sm_ltp_unquant sm) as [k|]; [| discriminate E]. destruct (sm_innovation_unquant sm) as [ki|]; [| discriminate E].
assert (K : bkeep b (if negb (sm_double_codebook sm =? 0) then innov_bits ki (innov_bits ki (hsg_bits sm (ltp_bits k b))) else innov_bits ki (hsg_bits sm (ltp_bits k b)))).
{ assert (K1 : bkeep b (ltp_bits k b)) by (destruct k; unfold ltp_bits, ltp3_bits; bkeep_tac).
assert (K2 : bkeep b (hsg_bits sm (ltp_bits k b))) by (eapply bkeep_trans; [exact K1|]; unfold hsg_bits; destruct (sm_have_subframe_gain sm =? 3); [| destruct (sm_have_subframe_gain sm =? 1)]; bkeep_tac).
assert (KI : forall b0, bkeep b0 (innov_bits ki b0)) by (intros b0; destruct ki; unfold innov_bits; [apply bkeep_refl| apply bkeep_scb]).
destruct (negb (sm_double_codebook sm =? 0)); [eapply bkeep_trans; [eapply bkeep_trans; [exact K2| apply KI]| apply KI] | eapply bkeep_trans; [exact K2| apply KI]]. }
cbv zeta in E. destruct (nb_submodeID st =? 1).
- destruct (voc_loop VOC_FUEL (nb_voc_offset st) olp); [| discriminate E]. injection E as _ <-. exact K.
- injection E as _ <-. exact K.
Qed.
Lemma bkeep_subframes : forall n sub sm olp st b st' b', subframes_pure n sub sm olp st b = Some (st', b') -> bkeep b b'.
Proof.
induction n as [|n IH]; intros sub sm olp st b st' b' E; cbn [subframes_pure] in E.
- injection E as _ <-. apply bkeep_refl.
- destruct (subframe_pure sm olp sub st b) as [[st1 b1]|] eqn:E1; [| discriminate E].
eapply bkeep_trans; [exact (bkeep_subframe _ _ _ _ _ _ _ E1)| exact (IH _ _ _ _ _ _ _ E)].
Qed.

Lemma segD_st_keep : forall (st : nb_state bptr) sm b,
nb_blk (segD_st st sm b) = nb_blk st /\ nb_first (segD_st st sm b) = nb_first st /\ nb_count_lost (segD_st st sm b) = nb_count_lost st
/\ nb_sampling_rate (segD_st st sm b) = nb_sampling_rate st /\ nb_innov_save (segD_st st sm b) = nb_innov_save st
/\ nb_pitch_gain_buf_idx (segD_st st sm b) = nb_pitch_gain_buf_idx st /\ nb_encode_submode (segD_st st sm b) = nb_encode_submode st
/\ nb_submodeID (segD_st st sm b) = nb_submodeID st /\ nb_lpc_enh_enabled (segD_st st sm b) = nb_lpc_enh_enabled st
/\ nb_stereo_cb (segD_st st sm b) = nb_stereo_cb st /\ nb_voc_offset (segD_st st sm b) = nb_voc_offset st
/\ nb_isWideband (segD_st st sm b) = nb_isWideband st /\ nb_highpass_enabled (segD_st st sm b) = nb_highpass_enabled st
/\ (nb_dtx_enabled (segD_st st sm b) = 0 \/ nb_dtx_enabled (segD_st st sm b) = 1 \/ nb_dtx_enabled (segD_st st sm b) = nb_dtx_enabled st).
Proof.
intros st sm b. unfold segD_st.
destruct (nb_submodeID st =? 1); [| destruct (1 <? nb_submodeID st)]; cbn;
(repeat (split; [reflexivity|])); [destruct (_ =? 15); [right; left| left]; reflexivity | left; reflexivity | right; right; reflexivity].
Qed.
Lemma subframes_blk : forall n sub sm olp (st : nb_state bptr) b st' b', subframes_pure n sub sm olp st b = Some (st', b') -> nb_blk st' = nb_blk st.
Proof.
induction n as [|n IH]; intros sub sm olp st b st' b' E; cbn [subframes_pure] in E; [injection E as <- _; reflexivity|].
destruct (subframe_pure sm olp sub st b) as [[st1 b1]|] eqn:E1; [| discriminate E].
rewrite (IH _ _ _ _ _ _ _ E). unfold subframe_pure in E1.
destruct (sm_ltp_unquant sm); [| discriminate E1]. destruct (sm_innovation_unquant sm); [| discriminate E1]. cbv zeta in E1.
destruct (nb_submodeID st =? 1); [destruct (voc_loop VOC_FUEL (nb_voc_offset st) olp); [| discriminate E1]|]; injection E1 as <- _; reflexivity.
Qed.

